var rules = []Rule{
	{ID: "resources.references-unreadable", Statement: english("The definitions cannot be updated; nothing was saved:\n%s"), ErrorKey: "error.resource_references_unreadable", Slots: []TermID{TermTeamDefinition}},
	{ID: "resources.references-write", Statement: english("Writing failed. Completed:\n%s\nNot completed:\n%s\n%s"), ErrorKey: "error.resource_references_write", Slots: []TermID{TermTeamDefinition, TermTeamDefinition, TermReason}},
	{ID: "refresh.no-pane", Statement: english("%s has no pane; {{refresh}} does not add a {{member}} to a running {{team}}."), Recovery: english("Use hergy apply to add it."), ErrorKey: "refresh.use_apply", Slots: []TermID{"member"}},
	{ID: "refresh.own-pane", Statement: english("%s runs in your own pane; a {{member}} cannot {{refresh}} itself. Run it from another pane, or as the {{human}}"), ErrorKey: "error.refresh_self", Slots: []TermID{"member"}},
	{ID: "refresh.busy-pane", Statement: english("%s: the pane named after it is running something else (pane %s); run `hergy down` then `hergy up`"), ErrorKey: "error.refresh_pane_busy", Slots: []TermID{"member", "place"}},
	{ID: "refresh.state", Statement: english("%s: {{status}}=%q; wait until the {{agent}} is {{idle}} or done"), ErrorKey: "error.reset_before_refresh", Slots: []TermID{"member", "status"}},
	{ID: "apply.run-changed", Statement: english("{{team|cap}} %[1]s was stopped or started again after this plan was made; run hergy apply --team %[1]s --dry to make a new plan, then {{apply}} it again"), Slots: []TermID{"team-name"}},
	{ID: "apply.env-changed", Statement: english("%s's environment changed, so hergy cannot {{apply}} it. [[env.fixed]]"), ErrorKey: "apply.refused_env", Slots: []TermID{"member"}},
	{ID: "apply.state", Statement: english("%s is {{working}} or {{waiting-for-permission}}, so hergy cannot {{apply}} it now"), ErrorKey: "apply.refused_state", Slots: []TermID{"member"}},
	{ID: "apply.removed", Statement: english("%s is no longer in the {{team-definition}}. Stop the {{team}} and {{start}} it again to {{apply}} this (hergy down, then hergy up)"), ErrorKey: "apply.refused_removed", Slots: []TermID{"member"}},
	{ID: "up.state-unavailable", Statement: english("cannot save the running {{team}} state: %v; make the state directory writable, then run hergy up again")},
	{ID: "up.name-taken", Statement: english("a {{team}} named %s is already running; {{start}} it under another name"), ErrorKey: "error.team_name_taken", Slots: []TermID{"team-name"}},
	{ID: "hire.purpose-outside", Statement: english("%[1]s cannot hire for \"%[2]s\"; it may hire for: %[3]s (team.yaml workers:). Pass one of those {{purpose}}s"), ErrorKey: "error.hire_purpose_outside", Slots: []TermID{"member", "purpose", "purpose"}},
	{ID: "hire.purpose-nobody", Statement: english("no {{member}} may hire a {{worker}} for \"%s\"; who may hire for what: %s. Pass one of those {{purpose}}s"), ErrorKey: "error.hire_purpose_nobody", Slots: []TermID{"purpose", "member"}},
	{ID: "hire.from-many", Statement: english("--from is required ({{member}}s hiring for this {{purpose}}: %s)"), ErrorKey: "error.from_required_many", Slots: []TermID{"member"}},
	{ID: "flag.as.up", Statement: english("{{start|cap}} the {{team}} under this {{team-name}} (default: the {{team-definition-name}})")},
	{ID: "flag.dry.up", Statement: english("Print the plan (each {{member}}'s {{prompt}} as text) and {{start}} nothing")},
	{ID: "flag.dry.down", Statement: english("Print what would close and close nothing")},
	{ID: "flag.json.status", Statement: english("Print the rows as JSON (state and unchanged_minutes) instead of text")},
	{ID: "flag.all.refresh", Statement: english("Restart every {{member}} (not with a {{member}})")},
	{ID: "flag.dry.refresh", Statement: english("Print what would restart or be added, and change nothing")},
	{ID: "flag.all.reprompt", Statement: english("Send it to every {{member}} (not with a {{member}})")},
	{ID: "flag.dry.reprompt", Statement: english("Print what would be sent and send nothing")},
	{ID: "flag.dry.apply", Statement: english("Print each {{member}}'s way of applying, what changed and the {{team}}'s {{rule-note}}s")},
	{ID: "flag.dry.nudge", Statement: english("Print what would be sent and send nothing")},
	{ID: "flag.dry.stop", Statement: english("Print what would {{stop}} and change nothing")},
	{ID: "flag.from.tell", Statement: english("The {{member}} or {{worker}} the message is from (short name or {{herdr-name}})")},
	{ID: "flag.dry.tell", Statement: english("Print what would be sent and send nothing")},
	{ID: "flag.purpose.hire", Statement: english("What the {{worker}} is for (required)")},
	{ID: "flag.task.hire", Statement: english("The task text handed to the {{worker}} (required)")},
	{ID: "flag.from.hire", Statement: english("The {{member}} that hires the {{worker}} (short {{member-name}} or {{herdr-name}})")},
	{ID: "flag.dry.hire", Statement: english("Print the plan and {{start}} nothing")},
	{ID: "flag.log.turns", Statement: english("Print the watcher's log (each line with its time) and {{stop}}")},
	{ID: "flag.dry.migrate", Statement: english("Inspect every conversion without writing")},
	{ID: "flag.global.migrate", Statement: english("Convert {{global}} settings instead of the {{project}}")},
	{ID: "flag.port.serve", Statement: english("The port to listen on (default 8787; 0 lets the operating system pick a free one)")},
	{ID: "flag.no-open.serve", Statement: english("Print the URL and open no browser")},
	{ID: "flag.ai.cheat", Statement: english("Print it for an {{agent}} (always English)")},
	{ID: "flag.lang", Statement: english("Language of the text handed to agents and of the starter files (default en)")},
	{ID: "flag.help", Statement: english("Show this text")},
	{ID: "flag.dir", Statement: english("The {{project}} root to resolve against")},
	{ID: "flag.json", Statement: english("With --dry, print the plan as JSON (--dry is required)")},
	{ID: "startup.timeout", Statement: english("Startup timeout in milliseconds, 3001..300000 (default 30000)")},
	{ID: "team.selection", Statement: english("The {{team}} to act on, by {{team-name}}.")},
	{ID: "hire.team-selection", Statement: english("The {{team}}, by {{team-name}} or {{team-definition-name}}.")},
	{ID: "env.fixed", Statement: english("env is fixed when a pane is made. After editing env, run hergy down then hergy up.")},
	{ID: "prompt.missing-receipt", Statement: english("not received: %s (pane %s): %s\nretry: %s"), ErrorKey: "launcher.undelivered", Slots: []TermID{"member", "place", "reason", "reprompt"}},
	{ID: "control.nudge-state", Statement: english("%s: {{status}} %q; a nudge is sent only when the {{agent}} is {{idle}} or done. Run it again then"), ErrorKey: "error.nudge_busy", Slots: []TermID{"member", "status"}},
	{ID: "control.stop-self", Statement: english("%s runs in your own pane; a {{member}} cannot {{stop}} itself. Run it from another pane, or as the {{human}}"), ErrorKey: "error.stop_self", Slots: []TermID{"member"}},
	{ID: "refresh.no-team-pane", Statement: english("%s: the {{team}} tab is absent or has no pane to split; run `hergy down` then `hergy up`"), ErrorKey: "error.refresh_no_pane", Slots: []TermID{"member"}},
	{ID: "start.cwd-directory", Statement: english("cwd is not a directory: %s; pass a directory to -C"), ErrorKey: "error.cwd_not_dir", Slots: []TermID{"place"}},
	{ID: "start.live-names", Statement: english("live {{agent}} names already in use: %s; run `hergy down`, then run this again"), ErrorKey: "error.live_names_in_use", Slots: []TermID{"herdr-name"}},
	{ID: "runtime.managed-pane", Statement: english("run inside a Herdr-managed shell pane (HERDR_ENV=1 and HERDR_PANE_ID are required)"), ErrorKey: "error.not_under_herdr"},
}
